import { test, expect } from '@playwright/test';

test.describe('PayPal Payment Method Selection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully select PayPal as payment method', async ({ page }) => {
    // Verify payment options are visible
    const paymentOptions = page.getByRole('group', { name: /payment options/i });
    await expect(paymentOptions).toBeVisible();

    // Verify PayPal option is visible and selectable
    const payPalOption = page.getByRole('button', { name: /paypal/i });
    await expect(payPalOption).toBeVisible();

    // Click PayPal option
    await payPalOption.click();

    // Verify PayPal is selected
    await expect(payPalOption).toHaveClass(/selected/);

    // Verify PayPal payment details are displayed
    const payPalDetails = page.getByText(/paypal/i);
    await expect(payPalDetails).toBeVisible();

    // Verify payment confirmation button is enabled
    const confirmButton = page.getByRole('button', { name: /confirm payment/i });
    await expect(confirmButton).toBeEnabled();

    // Click confirm payment
    await confirmButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/payment confirmed/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to order confirmation page
    await expect(page).toHaveURL(/.*\/order-confirmation/);
  });

  test('should handle PayPal option not being available', async ({ page }) => {
    // Intercept the API call to simulate PayPal being unavailable
    await page.route('**/api/payment/options', route => {
      route.abort('failed');
    });

    // Verify payment options are visible
    const paymentOptions = page.getByRole('group', { name: /payment options/i });
    await expect(paymentOptions).toBeVisible();

    // Attempt to click PayPal option
    const payPalOption = page.getByRole('button', { name: /paypal/i });
    await expect(payPalOption).toBeVisible();

    // Click PayPal option
    await payPalOption.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/paypal is currently unavailable/i);
    await expect(errorMessage).toBeVisible();

    // Verify PayPal option is not selected
    await expect(payPalOption).not.toHaveClass(/selected/);

    // Verify user is prompted to select another option
    const fallbackPrompt = page.getByText(/please select another payment method/i);
    await expect(fallbackPrompt).toBeVisible();

    // Verify other payment options are still available
    const creditCardOption = page.getByRole('button', { name: /credit card/i });
    await expect(creditCardOption).toBeVisible();

    // Verify user can select credit card
    await creditCardOption.click();
    await expect(creditCardOption).toHaveClass(/selected/);

    // Verify PayPal error persists
    await expect(errorMessage).toBeVisible();
  });
});
